Rules.InvariantScript:
Set(varMSF_Search, "");

ClearCollect(
    varMSF_Selected,
    FirstN(
        Table(
            {
                Id: "",
                Code: "",
                Display: "",
                SortOrder: 0
            }
        ),
        0
    )
);

ClearCollect(
    varMSF_Invalid,
    FirstN(
        Table({ Code: "" }),
        0
    )
)

If(
    IsBlank(
        LookUp(
            varMSF_Selected,
            Code = ThisItem.Code
        )
    ),
    Collect(
        varMSF_Selected,
        {
            Id: ThisItem.Id,
            Code: ThisItem.Code,
            Display: ThisItem.Display,
            SortOrder: ThisItem.SortOrder
        }
    )
)

ClearCollect(
    varMSF_Selected,
    FirstN(
        Table(
            {
                Id: "",
                Code: "",
                Display: "",
                SortOrder: 0
            }
        ),
        0
    )
);

ClearCollect(
    varMSF_Invalid,
    FirstN(
        Table({ Code: "" }),
        0
    )
);

Set(varMSF_Search, "");

Reset(txtMSF_Search);
Reset(txtMSF_Paste);
Reset(galMSF_Items)

If(
    cmp_MultiSelectFilter.EnablePaste && !IsBlank(Trim(txtMSF_Paste.Text)),

    With(
        {
            _rawCodes:
                ForAll(
                    Split(
                        Substitute(
                            Substitute(
                                Substitute(txtMSF_Paste.Text, Char(13), ""),
                                ";",
                                Char(10)
                            ),
                            ",",
                            Char(10)
                        ),
                        Char(10)
                    ),
                    { Code: Upper(Trim(Value)) }
                )
        },
        With(
            {
                _cleanCodes:
                    Distinct(
                        Filter(_rawCodes, !IsBlank(Code)),
                        Code
                    )
            },
            ClearCollect(
                varMSF_Selected,
                Filter(
                    cmp_MultiSelectFilter.Items,
                    Code in _cleanCodes.Value
                )
            );

            ClearCollect(
                varMSF_Invalid,
                RenameColumns(
                    Filter(
                        _cleanCodes,
                        !(Value in cmp_MultiSelectFilter.Items.Code)
                    ),
                    Value,
                    Code
                )
            );

            Reset(txtMSF_Paste)
        )
    )
);

cmp_MultiSelectFilter.OnApply();
cmp_MultiSelectFilter.OnClose()
